[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>SnapFrame — Capture, Create & Share What You Love</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    :root {
      --black: #000000;
      --white: #ffffff;
      --purple: #7638FA;
      --orange: #FF7A00;
      --magenta: #E040A0;
      --bg: #FAFAFA;
      --gray-100: #F5F5F5;
      --gray-200: #EEEEEE;
      --gray-300: #E0E0E0;
      --gray-500: #9E9E9E;
      --gray-700: #616161;
      --gray-800: #424242;
      --gray-900: #212121;
      --radius: 16px;
      --radius-sm: 10px;
      --radius-pill: 999px;
      --gradient-hero: linear-gradient(135deg, #7638FA 0%, #E040A0 50%, #FF7A00 100%);
      --gradient-accent: linear-gradient(90deg, #7638FA, #E040A0, #FF7A00);
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      background: var(--white);
      color: var(--gray-900);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      overflow-x: hidden;
    }

    a { text-decoration: none; color: inherit; }
    button { cursor: pointer; border: none; background: none; font-family: inherit; }
    img { max-width: 100%; display: block; }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* ── HEADER ── */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
      background: rgba(255, 255, 255, 0.92);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-bottom: 1px solid var(--gray-200);
      transition: box-shadow 0.3s;
    }

    .header.scrolled {
      box-shadow: 0 2px 20px rgba(0,0,0,0.06);
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 64px;
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-weight: 800;
      font-size: 1.25rem;
      color: var(--black);
    }

    .logo-icon {
      width: 36px;
      height: 36px;
      background: var(--gradient-hero);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg { width: 20px; height: 20px; }

    .header-right {
      display: flex;
      align-items: center;
      gap: 16px;
    }

    .btn-login {
      padding: 8px 24px;
      border-radius: var(--radius-pill);
      font-weight: 600;
      font-size: 0.875rem;
      color: var(--white);
      background: var(--black);
      transition: opacity 0.2s;
    }

    .btn-login:hover { opacity: 0.85; }

    .hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      width: 28px;
      padding: 4px 0;
      z-index: 1001;
    }

    .hamburger span {
      display: block;
      height: 2.5px;
      width: 100%;
      background: var(--black);
      border-radius: 2px;
      transition: all 0.3s ease;
    }

    .hamburger.active span:nth-child(1) {
      transform: translateY(7.5px) rotate(45deg);
    }

    .hamburger.active span:nth-child(2) {
      opacity: 0;
    }

    .hamburger.active span:nth-child(3) {
      transform: translateY(-7.5px) rotate(-45deg);
    }

    .mobile-nav {
      display: none;
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: var(--white);
      z-index: 999;
      padding: 100px 32px 40px;
      flex-direction: column;
      gap: 8px;
      overflow-y: auto;
    }

    .mobile-nav.open { display: flex; }

    .mobile-nav a {
      font-size: 1.5rem;
      font-weight: 700;
      padding: 16px 0;
      color: var(--gray-900);
      border-bottom: 1px solid var(--gray-200);
      transition: color 0.2s;
    }

    .mobile-nav a:hover { color: var(--purple); }

    .mobile-nav .btn-login-mobile {
      margin-top: 24px;
      display: inline-block;
      text-align: center;
      padding: 16px 32px;
      background: var(--black);
      color: var(--white);
      border-radius: var(--radius-pill);
      font-size: 1.125rem;
      font-weight: 600;
    }

    @media (max-width: 768px) {
      .hamburger { display: flex; }
      .btn-login { display: none; }
    }

    /* ── HERO ── */
    .hero {
      padding: 140px 0 100px;
      position: relative;
      overflow: hidden;
      background: var(--white);
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -30%;
      right: -20%;
      width: 70%;
      height: 120%;
      background: radial-gradient(ellipse, rgba(118, 56, 250, 0.08) 0%, rgba(224, 64, 160, 0.05) 40%, transparent 70%);
      pointer-events: none;
    }

    .hero::after {
      content: '';
      position: absolute;
      bottom: -10%;
      left: -10%;
      width: 50%;
      height: 60%;
      background: radial-gradient(ellipse, rgba(255, 122, 0, 0.06) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero .container {
      position: relative;
      z-index: 1;
      text-align: center;
      max-width: 900px;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 8px 20px;
      background: var(--gray-100);
      border-radius: var(--radius-pill);
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--gray-700);
      margin-bottom: 32px;
    }

    .hero-badge span {
      background: var(--gradient-accent);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .hero h1 {
      font-size: clamp(2.5rem, 6vw, 4rem);
      font-weight: 800;
      line-height: 1.1;
      letter-spacing: -0.03em;
      color: var(--black);
      margin-bottom: 28px;
    }

    .hero h1 .gradient-text {
      background: var(--gradient-accent);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .hero p {
      font-size: 1.2rem;
      color: var(--gray-700);
      max-width: 600px;
      margin: 0 auto 40px;
      line-height: 1.7;
    }

    .btn-cta {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      padding: 16px 40px;
      background: var(--gradient-hero);
      color: var(--white);
      font-weight: 700;
      font-size: 1.1rem;
      border-radius: var(--radius-pill);
      transition: transform 0.2s, box-shadow 0.2s;
      box-shadow: 0 4px 24px rgba(118, 56, 250, 0.3);
    }

    .btn-cta:hover {
      transform: translateY(-2px);
      box-shadow: 0 8px 32px rgba(118, 56, 250, 0.4);
    }

    .btn-cta svg {
      width: 18px;
      height: 18px;
      transition: transform 0.2s;
    }

    .btn-cta:hover svg { transform: translateX(3px); }

    /* ── FEATURES ── */
    .section { padding: 100px 0; }

    .features {
      background: var(--white);
    }

    .section-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 60px;
      align-items: center;
    }

    .section-label {
      display: inline-block;
      font-size: 0.8rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: var(--purple);
      margin-bottom: 16px;
    }

    .section-headline {
      font-size: clamp(2rem, 4vw, 2.75rem);
      font-weight: 800;
      line-height: 1.15;
      letter-spacing: -0.02em;
      color: var(--black);
      margin-bottom: 20px;
    }

    .section-desc {
      font-size: 1.05rem;
      color: var(--gray-700);
      line-height: 1.75;
      margin-bottom: 28px;
    }

    .section-link {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-weight: 700;
      font-size: 1rem;
      color: var(--purple);
      transition: gap 0.2s;
    }

    .section-link:hover { gap: 12px; }

    .section-visual {
      position: relative;
      border-radius: 24px;
      overflow: hidden;
      aspect-ratio: 4/3;
    }

    .features .section-visual {
      background: linear-gradient(135deg, #F0E6FF 0%, #FFE0F0 50%, #FFF0E0 100%);
    }

    .visual-inner {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .feature-icons {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 20px;
      padding: 40px;
      width: 100%;
    }

    .feature-icon-card {
      background: rgba(255,255,255,0.85);
      backdrop-filter: blur(8px);
      border-radius: var(--radius);
      padding: 24px;
      text-align: center;
      transition: transform 0.3s;
    }

    .feature-icon-card:hover { transform: translateY(-4px); }

    .feature-icon-card .icon {
      width: 48px;
      height: 48px;
      margin: 0 auto 12px;
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .feature-icon-card .icon svg {
      width: 24px;
      height: 24px;
    }

    .feature-icon-card .icon.clips { background: linear-gradient(135deg, #7638FA, #A855F7); }
    .feature-icon-card .icon.stories { background: linear-gradient(135deg, #E040A0, #F472B6); }
    .feature-icon-card .icon.dms { background: linear-gradient(135deg, #FF7A00, #FBBF24); }
    .feature-icon-card .icon.explore { background: linear-gradient(135deg, #06B6D4, #7638FA); }

    .feature-icon-card span {
      font-size: 0.85rem;
      font-weight: 700;
      color: var(--gray-800);
    }

    /* ── SAFETY ── */
    .safety {
      background: var(--gray-100);
    }

    .safety .section-label { color: #059669; }

    .safety .section-visual {
      background: linear-gradient(135deg, #D1FAE5 0%, #ECFDF5 50%, #F0FFF4 100%);
    }

    .safety .section-link { color: #059669; }

    .safety-icons {
      display: flex;
      flex-direction: column;
      gap: 16px;
      padding: 40px;
      width: 100%;
    }

    .safety-item {
      display: flex;
      align-items: center;
      gap: 16px;
      background: rgba(255,255,255,0.9);
      backdrop-filter: blur(8px);
      border-radius: 14px;
      padding: 20px 24px;
      transition: transform 0.2s;
    }

    .safety-item:hover { transform: translateX(4px); }

    .safety-item .s-icon {
      width: 44px;
      height: 44px;
      border-radius: 12px;
      background: #ECFDF5;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }

    .safety-item .s-icon svg { width: 22px; height: 22px; color: #059669; }

    .safety-item span {
      font-weight: 600;
      font-size: 0.95rem;
      color: var(--gray-800);
    }

    /* ── CREATORS ── */
    .creators {
      background: var(--white);
    }

    .creators .section-visual {
      background: linear-gradient(135deg, #FFF7ED 0%, #FFEDD5 50%, #FEF3C7 100%);
    }

    .creators .section-label { color: var(--orange); }
    .creators .section-link { color: var(--orange); }

    .creator-visual-content {
      padding: 40px;
      width: 100%;
      display: flex;
      flex-direction: column;
      gap: 16px;
    }

    .creator-stat-card {
      background: rgba(255,255,255,0.9);
      backdrop-filter: blur(8px);
      border-radius: 14px;
      padding: 20px 24px;
      display: flex;
      align-items: center;
      gap: 16px;
      transition: transform 0.2s;
    }

    .creator-stat-card:hover { transform: translateX(4px); }

    .creator-stat-card .c-icon {
      width: 44px;
      height: 44px;
      border-radius: 12px;
      background: #FFF7ED;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }

    .creator-stat-card .c-icon svg { width: 22px; height: 22px; color: var(--orange); }

    .creator-stat-card span {
      font-weight: 600;
      font-size: 0.95rem;
      color: var(--gray-800);
    }

    @media (max-width: 768px) {
      .section-grid {
        grid-template-columns: 1fr;
        gap: 40px;
      }
      .section-grid.reverse .section-visual { order: -1; }
      .section { padding: 72px 0; }
    }

    /* ── TAGLINE BANNER ── */
    .tagline-banner {
      padding: 80px 0;
      background: var(--black);
      position: relative;
      overflow: hidden;
    }

    .tagline-banner::before {
      content: '';
      position: absolute;
      inset: 0;
      background: var(--gradient-hero);
      opacity: 0.12;
    }

    .tagline-banner .container {
      position: relative;
      text-align: center;
    }

    .tagline-banner h2 {
      font-size: clamp(2rem, 5vw, 3.5rem);
      font-weight: 800;
      line-height: 1.15;
      letter-spacing: -0.02em;
      color: var(--white);
    }

    .tagline-banner h2 .gradient-text {
      background: var(--gradient-accent);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    /* ── NEWS CAROUSEL ── */
    .news {
      padding: 100px 0;
      background: var(--gray-100);
    }

    .news-header {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      margin-bottom: 48px;
      gap: 16px;
      flex-wrap: wrap;
    }

    .news-header-left .section-label { margin-bottom: 8px; }

    .news-header h2 {
      font-size: clamp(1.75rem, 3.5vw, 2.5rem);
      font-weight: 800;
      letter-spacing: -0.02em;
      color: var(--black);
    }

    .news-view-more {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-weight: 700;
      font-size: 0.95rem;
      color: var(--purple);
      transition: gap 0.2s;
      white-space: nowrap;
    }

    .news-view-more:hover { gap: 10px; }

    .carousel-wrapper {
      position: relative;
    }

    .carousel-track {
      display: flex;
      gap: 24px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: none;
      padding-bottom: 8px;
    }

    .carousel-track::-webkit-scrollbar { display: none; }

    .news-card {
      flex: 0 0 320px;
      scroll-snap-align: start;
      background: var(--white);
      border-radius: 20px;
      overflow: hidden;
      transition: transform 0.3s, box-shadow 0.3s;
      cursor: pointer;
    }

    .news-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 12px 40px rgba(0,0,0,0.08);
    }

    .news-card-thumb {
      width: 100%;
      aspect-ratio: 16/10;
      position: relative;
      overflow: hidden;
